function gardenStage(days){
  if(days>=31)return 5;
  if(days>=23)return 4;
  if(days>=15)return 3;
  if(days>=7)return 2;
  if(days>=1)return 1;
  return 0;
}
function gardenMessage(days){
  if(days>=31)return ['¡Tu jardín ha florecido!','Has cuidado tu vida espiritual durante todo el mes. Que lo sembrado continúe dando fruto.'];
  if(days>=23)return ['Tu jardín está floreciendo','Tu constancia ya se nota. Sigue acercándote a Dios un día a la vez.'];
  if(days>=15)return ['Ya aparecen las primeras flores','Has llegado a la mitad del camino. Dios sigue trabajando en tu corazón.'];
  if(days>=7)return ['Tu planta está echando hojas','Una semana de constancia está creando raíces fuertes.'];
  if(days>=1)return ['La primera semilla despertó','Cada encuentro con Dios riega el jardín de tu corazón.'];
  return ['Tu semilla está lista','Completa tu primer devocional para comenzar a verla crecer.'];
}
function updateGarden(days){
  const stage=gardenStage(days),pct=Math.round(days/31*100),msg=gardenMessage(days);
  ['gardenPlant','homeGardenPlant'].forEach(id=>{const node=el(id);if(node)node.className='gardenPlant stage-'+stage});
  if(el('gardenStageTitle'))el('gardenStageTitle').textContent=msg[0];
  if(el('gardenEncouragement'))el('gardenEncouragement').textContent=msg[1];
  if(el('gardenMeterFill'))el('gardenMeterFill').style.width=pct+'%';
  if(el('gardenCount'))el('gardenCount').textContent=`${days} de 31 días • ${pct}%`;
  if(el('homeGardenProgress'))el('homeGardenProgress').textContent=days?`${days} de 31 devocionales completados. Tu jardín sigue creciendo.`:'Comienza hoy y observa cómo florece tu constancia.';
}
