/* Música instrumental de fondo — edición agosto 2026 */
const MUSIC_PREF_KEY = 'jardinOracion_musicEnabled';
function musicAudio(){ return el('backgroundMusic'); }
function musicIsEnabled(){ return localStorage.getItem(MUSIC_PREF_KEY) !== 'false'; }
function updateMusicControls(){
  const audio=musicAudio();
  const playing=audio && !audio.paused;
  const floating=el('musicToggle');
  const section=el('musicSectionButton');
  if(floating){
    floating.textContent=playing?'🔊 Música':'🔇 Música';
    floating.setAttribute('aria-label',playing?'Silenciar música':'Activar música');
    floating.classList.toggle('playing',playing);
  }
  if(section) section.textContent=playing?'⏸️ Pausar música':'▶️ Reproducir música';
}
async function startBackgroundMusic(){
  const audio=musicAudio();
  if(!audio)return;
  audio.volume=0.28;
  try{
    await audio.play();
    localStorage.setItem(MUSIC_PREF_KEY,'true');
  }catch(err){
    console.info('El navegador requiere tocar un botón para comenzar la música.');
  }
  updateMusicControls();
}
function pauseBackgroundMusic(remember=true){
  const audio=musicAudio();
  if(audio)audio.pause();
  if(remember)localStorage.setItem(MUSIC_PREF_KEY,'false');
  updateMusicControls();
}
function toggleBackgroundMusic(){
  const audio=musicAudio();
  if(!audio)return;
  if(audio.paused) startBackgroundMusic(); else pauseBackgroundMusic(true);
}
const WELCOME_HIDE_KEY = 'jardinOracion_hideWelcomeDate';
const welcomePhrases = [
  'Hoy Dios quiere encontrarse contigo.',
  'Respira: no tienes que cargarlo todo sola.',
  'La gracia de Dios también alcanza este día.',
  'Tu historia todavía está en las manos de Dios.',
  'Este momento puede ser el comienzo de algo nuevo.',
  'Dios puede hacer florecer lo que parecía seco.',
  'Ven tal como estás; Dios conoce tu corazón.'
];
function localDateKey(){
  const d=new Date();
  return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
}
function prepareWelcomeContent(){
  const phrase=el('welcomeDailyPhrase');
  const date=el('welcomeDate');
  const dayIndex=Math.abs(new Date().getDate()-1)%welcomePhrases.length;
  if(phrase)phrase.textContent=welcomePhrases[dayIndex];
  if(date)date.textContent=new Intl.DateTimeFormat('es-US',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());
}
function closeMusicWelcome(){
  const modal=el('musicWelcome');
  const hideToday=el('hideWelcomeToday');
  if(hideToday?.checked)localStorage.setItem(WELCOME_HIDE_KEY,localDateKey());
  if(modal){modal.classList.remove('visible'); setTimeout(()=>{modal.hidden=true;},260);}
  sessionStorage.setItem('jardinOracion_welcomeSeen','true');
}
function enterWithMusic(){ closeMusicWelcome(); startBackgroundMusic(); }
function enterSilently(){ closeMusicWelcome(); pauseBackgroundMusic(true); }
function setupBackgroundMusic(){
  const audio=musicAudio();
  if(audio){
    audio.volume=0.28;
    audio.addEventListener('play',updateMusicControls);
    audio.addEventListener('pause',updateMusicControls);
  }
  updateMusicControls();
  prepareWelcomeContent();
  const modal=el('musicWelcome');
  const hiddenToday=localStorage.getItem(WELCOME_HIDE_KEY)===localDateKey();
  if(modal && !sessionStorage.getItem('jardinOracion_welcomeSeen') && !hiddenToday){
    modal.hidden=false;
    requestAnimationFrame(()=>modal.classList.add('visible'));
  }
}
document.addEventListener('DOMContentLoaded',()=>{setupBackgroundMusic(); if(el('jDate')&&!el('jDate').value)el('jDate').value=todayUS(); renderJournal();});


